// A browser error document is not evidence of which application site failed.
// Only a retained failure in the same owned main frame supplies that cause.
export function browserErrorPageCause(url, hasFailedDocument) {
  if (url !== "chrome-error://chromewebdata/") return undefined;
  return hasFailedDocument ? "unreachable" : "unknown";
}

// Request-stage enforcement for the fresh, Runner-owned Chromium browser.
// Attribute documents using the owned page's public Chromium Page session.
export async function installNavigationPolicy({
  browser,
  context,
  hostAllowed,
  latchNavigation,
  observe,
  onError,
  signal,
  deadline,
}) {
  const frames = new Map(),
    pages = new Map(),
    pending = new Map();
  let closing = false,
    failure,
    resolveFailure;
  const failed = new Promise((resolve) => {
    resolveFailure = resolve;
  });
  const fail = (error) => {
    if (closing || failure) return;
    failure = error instanceof Error ? error : new Error(String(error));
    onError(`Navigation Fetch failure: ${failure.message}`);
    resolveFailure(failure);
  };
  // Resolving the failure latch avoids an unhandled rejected event promise.
  const wait = (promise) =>
    Promise.race([
      promise,
      failed.then((error) => {
        throw error;
      }),
    ]);
  const waitForAction = async (promise) => {
    const result = await wait(promise);
    // An action can return before a paused popup request is classified.
    while (pending.size)
      await wait(
        Promise.all([...pending.values()].map(({ settled }) => settled)),
      );
    return result;
  };
  const abort = () => fail(new Error("Navigation guard interrupted"));
  const timer = setTimeout(
    () => fail(new Error("Time limit")),
    Math.max(1, deadline - Date.now()),
  );
  signal?.addEventListener("abort", abort, { once: true });
  if (signal?.aborted) abort();
  let session;
  const remove = (id) => {
    const removed = new Set([id]);
    for (const current of removed)
      for (const [child, record] of frames)
        if (record.parent === current) removed.add(child);
    for (const current of removed) frames.delete(current);
  };
  const invalidate = (owner) => {
    for (const [id, record] of frames)
      if (record.owner === owner) frames.delete(id);
  };
  const classify = (id) => {
    const seen = new Set();
    let record = frames.get(id);
    const owner = record?.owner;
    if (!record || !pages.has(owner)) return "unknown";
    const child = Boolean(record.parent);
    const attached = record.attached;
    while (record.parent) {
      if (seen.has(record.parent)) return "unknown";
      seen.add(record.parent);
      record = frames.get(record.parent);
      // A live Page session's attachment proves a child even when the
      // popup committed its root before this session began observing it.
      if (!record) return attached ? "subframe" : "unknown";
      if (record.owner !== owner) return "unknown";
    }
    return child ? "subframe" : "main-frame";
  };
  const confirmsChild = (tree, frameId) => {
    const root = tree?.frame;
    if (!root?.id || root.parentId || !hostAllowed(root.url)) return false;
    const seen = new Set([root.id]);
    const descendants = (parent) =>
      (parent.childFrames ?? []).some((child) => {
        const frame = child.frame;
        if (
          !frame?.id ||
          frame.parentId !== parent.frame.id ||
          seen.has(frame.id)
        )
          return false;
        seen.add(frame.id);
        return frame.id === frameId || descendants(child);
      });
    return descendants(tree);
  };
  const arm = async (page, primeTree = false) => {
    if (pages.has(page) || closing) return;
    const entry = { popup: !primeTree, ready: false, revision: 0 };
    pages.set(page, entry);
    const buffered = [];
    let primed = false;
    const apply = (kind, event) => {
      entry.revision++;
      if (kind === "detach") {
        // Chromium's OOPIF renderer swap preserves the logical frame/parent.
        // A remove destroys the logical frame and all known descendants.
        if (event.reason !== "swap") remove(event.frameId);
        return;
      }
      const id = event.frameId ?? event.frame?.id;
      const parent = event.parentFrameId ?? event.frame?.parentId ?? null;
      if (
        typeof id !== "string" ||
        !id ||
        parent === id ||
        (kind === "attach" && (typeof parent !== "string" || !parent))
      ) {
        if (id) remove(id);
        return;
      }
      const previous = frames.get(id);
      if (previous && (previous.owner !== page || previous.parent !== parent))
        remove(id);
      frames.set(id, {
        owner: page,
        parent,
        attached:
          kind === "attach" ||
          (previous?.owner === page &&
            previous.parent === parent &&
            previous.attached),
      });
    };
    const event = (kind, value) => {
      try {
        if (!primed) buffered.push([kind, value]);
        else apply(kind, value);
      } catch (error) {
        fail(error);
      }
    };
    try {
      const cdp = await wait(context.newCDPSession(page));
      entry.session = cdp;
      cdp.on("Page.frameAttached", (value) => event("attach", value));
      cdp.on("Page.frameNavigated", (value) => event("navigate", value));
      cdp.on("Page.frameDetached", (value) => event("detach", value));
      const closed = () => {
        invalidate(page);
        pages.delete(page);
      };
      page.on("close", closed);
      cdp.on("close", () => {
        closed();
        if (!closing && !page.isClosed())
          fail(new Error("Frame attribution session closed"));
      });
      await wait(cdp.send("Page.enable"));
      // Prime the existing blank page before browser Fetch exists. New
      // pages begin with events and may already have a paused Document.
      if (primeTree) {
        const { frameTree } = await wait(cdp.send("Page.getFrameTree"));
        if (page.isClosed() || !pages.has(page)) return;
        const snapshot = (tree) => {
          apply("navigate", { frame: tree.frame });
          for (const child of tree.childFrames ?? []) snapshot(child);
        };
        snapshot(frameTree);
      }
      for (const [kind, value] of buffered) apply(kind, value);
      primed = true;
      entry.ready = true;
      for (const record of pending.values()) record.probe?.(page, entry);
    } catch (error) {
      invalidate(page);
      if (!page.isClosed()) fail(error);
    }
  };
  const onPage = (page) => {
    void arm(page).catch(fail);
  };
  const beginCleanup = () => {
    closing = true;
    clearTimeout(timer);
    signal?.removeEventListener("abort", abort);
    context.off("page", onPage);
    // Do not disable Fetch or detach a live session: that can release pauses.
    // The owned browser/context close is the enforcement lifetime boundary.
    for (const [requestId, record] of pending)
      if (!record.dispatched) {
        record.dispatched = true;
        void session
          ?.send("Fetch.failRequest", { requestId, errorReason: "Aborted" })
          .catch(() => {});
      }
  };
  try {
    session = await wait(browser.newBrowserCDPSession());
    session.on("close", () =>
      fail(new Error("Browser interception session closed")),
    );
    session.on("Fetch.requestPaused", (event) => {
      if (!event || typeof event.requestId !== "string" || !event.requestId) {
        fail(new Error("Malformed paused Document request identity"));
        return;
      }
      const record = { dispatched: false };
      pending.set(event.requestId, record);
      record.settled = (async () => {
        const allowedHost = hostAllowed(event.request.url);
        let classification = allowedHost
          ? "host-allowed"
          : classify(event.frameId);
        if (classification === "unknown" && !failure && !closing) {
          // Keep Fetch paused while the browser delivers frame attribution.
          // The timeout never grants authority to an unresolved request.
          const grace = Math.max(0, Math.min(100, deadline - Date.now()));
          const childProofs = [];
          // A popup can commit its approved page before Page.enable observes
          // the first child attachment. Query only live, armed popups within
          // the same grace window. An absent reply grants no authority.
          record.probe = (page, entry) => {
            if (!entry.popup || !entry.ready || record.dispatched) return;
            const revision = entry.revision;
            void entry.session
              .send("Page.getFrameTree")
              .then(({ frameTree }) => {
                if (confirmsChild(frameTree, event.frameId))
                  childProofs.push({ page, entry, revision });
              })
              .catch(() => {});
          };
          for (const [page, entry] of pages) record.probe(page, entry);
          await new Promise((resolve) => setTimeout(resolve, grace));
          record.probe = undefined;
          if (record.dispatched) return;
          classification = classify(event.frameId);
          if (
            classification === "unknown" &&
            childProofs.filter(
              ({ page, entry, revision }) =>
                pages.get(page) === entry &&
                !page.isClosed() &&
                entry.revision === revision,
            ).length === 1
          )
            classification = "subframe";
        }
        const allowed =
          !failure &&
          !closing &&
          (allowedHost || classification === "subframe");
        observe(classification, allowed);
        if (!allowed && !failure && !closing)
          latchNavigation(event.request.url, classification, "fetch");
        record.dispatched = true;
        await wait(
          session.send(
            allowed ? "Fetch.continueRequest" : "Fetch.failRequest",
            {
              requestId: event.requestId,
              ...(!allowed ? { errorReason: "BlockedByClient" } : {}),
            },
          ),
        );
      })()
        .catch(fail)
        .finally(() => pending.delete(event.requestId));
    });
    for (const page of context.pages()) await arm(page, true);
    if (failure) throw failure;
    context.on("page", onPage);
    await wait(
      session.send("Fetch.enable", {
        patterns: [
          {
            urlPattern: "*",
            resourceType: "Document",
            requestStage: "Request",
          },
        ],
      }),
    );
    return { wait: waitForAction, beginCleanup };
  } catch (error) {
    fail(error);
    beginCleanup();
    throw error;
  }
}
